-- Scores de chaleur — calcul initial du 18/09/2026 (prospects uniquement)
begin;

create table if not exists ia_scores (
  enterprise_id uuid primary key references enterprises(id) on delete cascade,
  score smallint not null check (score between 1 and 5),
  reason text not null,
  model text,
  source text,
  computed_at timestamptz not null default now()
);
alter table ia_scores enable row level security;
drop policy if exists "ia_scores lecture" on ia_scores;
create policy "ia_scores lecture" on ia_scores for select to authenticated using (true);
